// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Parts and content analysis (prefactor)"
// Changes: Tests of the part helpers – read, write and compare each of the four parts of project content.

import { describe, expect, it } from 'vitest'
import { loadPrecExample } from './precOps'
import { defaultProjectData, type ProjectData } from './project'
import { PARTS, changedParts, partEquals, readPart, readParts, writePart, writeParts } from './parts'

function project(): ProjectData {
  const d = loadPrecExample(defaultProjectData())
  return {
    ...d,
    ll: { grammar: 'E -> i', input: 'i' },
    def: { nonterminals: 'E', terminals: 'i', start: 'E' },
    names: { map: '+ PLUS', ntPrefix: 'N_', tPrefix: 'T_', precPrefix: 'P_' },
  }
}

describe('parts', () => {
  it('are the definition, grammar rules, precedence table and reduction rules', () => {
    expect(PARTS).toEqual(['definition', 'grammarRules', 'precTable', 'reductionRules'])
  })

  it('reads each part of a project', () => {
    const d = project()
    expect(readPart(d, 'definition')).toEqual({ nonterminals: 'E', terminals: 'i', start: 'E' })
    expect(readPart(d, 'grammarRules')).toBe('E -> i')
    expect(readPart(d, 'reductionRules')).toBe('E -> E + E\nE -> E * E\nE -> ( E )\nE -> i')
    expect(readPart(d, 'precTable').terminals).toEqual(['i', '+', '*', '(', ')'])
    expect(readPart(d, 'precTable').cells).toEqual(d.prec.cells)
  })

  it('writing the grammar rules leaves the other parts, export naming and simulation inputs untouched', () => {
    const d = project()
    const next = writePart(d, 'grammarRules', 'E -> ( E )')
    expect(next.ll.grammar).toBe('E -> ( E )')
    expect(next).toEqual({ ...d, ll: { ...d.ll, grammar: 'E -> ( E )' } })
    expect(d.ll.grammar).toBe('E -> i')
  })

  it('writing the precedence table keeps the reduction rules and the precedence simulation input', () => {
    const d = project()
    const next = writePart(d, 'precTable', { terminals: ['+'], cells: {} })
    expect(readPart(next, 'precTable')).toEqual({ terminals: ['+'], cells: {} })
    expect(next.prec.rules).toBe(d.prec.rules)
    expect(next.prec.input).toBe('i + i * i')
    expect(next.names).toEqual(d.names)
  })

  it('writing the precedence table drops relations of terminals it does not have and never takes $ as a terminal', () => {
    const d = project()
    const { cells } = readPart(d, 'precTable')
    const next = writePart(d, 'precTable', { terminals: ['+', '$', '+', 'i'], cells })
    const table = readPart(next, 'precTable')
    expect(table.terminals).toEqual(['+', 'i'])
    expect(Object.keys(table.cells).length).toBe(7) // + i $ on both sides, minus the empty i·i and $·$
  })

  it('writing the definition and the reduction rules touches only them', () => {
    const d = project()
    const def = writePart(d, 'definition', { nonterminals: 'E\nF', terminals: 'i', start: 'F' })
    expect(def).toEqual({ ...d, def: { nonterminals: 'E\nF', terminals: 'i', start: 'F' } })
    const red = writePart(d, 'reductionRules', 'E -> i')
    expect(red).toEqual({ ...d, prec: { ...d.prec, rules: 'E -> i' } })
  })

  it('a written part does not share state with the value it was written from', () => {
    const value = { terminals: ['+'], cells: {} as Record<string, '<' | '=' | '>'> }
    const next = writePart(project(), 'precTable', value)
    value.terminals.push('*')
    expect(readPart(next, 'precTable').terminals).toEqual(['+'])
  })
})

describe('comparing parts', () => {
  it('finds a project equal to itself in every part', () => {
    const d = project()
    for (const part of PARTS) expect(partEquals(part, d, structuredClone(d)), part).toBe(true)
    expect(changedParts(d, structuredClone(d))).toEqual([])
  })

  it('ignores export naming and simulation inputs', () => {
    const d = project()
    const other = { ...d, ll: { ...d.ll, input: 'i i' }, prec: { ...d.prec, input: '' }, names: { ...d.names, map: '' } }
    expect(changedParts(d, other)).toEqual([])
  })

  it('names exactly the parts that differ', () => {
    const d = project()
    const other = writePart(writePart(d, 'grammarRules', 'E -> ( E )'), 'definition', { ...d.def, start: '' })
    expect(changedParts(d, other)).toEqual(['definition', 'grammarRules'])
    expect(partEquals('precTable', d, other)).toBe(true)
  })

  it('sees a changed relation, a reordered terminal list and a cleared cell as a changed precedence table', () => {
    const d = project()
    const cells = readPart(d, 'precTable').cells
    const key = Object.keys(cells)[0]
    const { [key]: _gone, ...without } = cells
    expect(partEquals('precTable', d, writePart(d, 'precTable', { terminals: d.prec.terminals, cells: without }))).toBe(false)
    expect(partEquals('precTable', d, writePart(d, 'precTable', { terminals: ['+', 'i', '*', '(', ')'], cells }))).toBe(false)
  })

  it('does not care in which order the relations were set', () => {
    const d = project()
    const reversed = Object.fromEntries(Object.entries(d.prec.cells).reverse())
    expect(partEquals('precTable', d, { ...d, prec: { ...d.prec, cells: reversed } })).toBe(true)
  })
})

describe('all parts at once', () => {
  it('reads the four parts and writes them into other content, keeping its export naming and simulation inputs', () => {
    const source = project()
    const target = { ...defaultProjectData(), ll: { grammar: '', input: 'x' }, names: { ...source.names, map: 'z Z' } }
    const merged = writeParts(target, readParts(source))
    expect(changedParts(merged, source)).toEqual([])
    expect(merged.ll.input).toBe('x')
    expect(merged.prec.input).toBe('')
    expect(merged.names.map).toBe('z Z')
  })

  it('writes only the parts it is given', () => {
    const d = project()
    const merged = writeParts(d, { reductionRules: 'E -> i' })
    expect(changedParts(d, merged)).toEqual(['reductionRules'])
  })
})
